import type { Metadata } from "next";
import { BRAND, COMMERCIAL, CONTACT, SERVICE_AREAS, SOCIAL } from "./brand";
import { listPriceBounds } from "./shop";

/**
 * Every indexable page shares a card generated by /og from its own title; noindex pages keep the
 * static one. A page may pass its own JPEG/PNG instead.
 */
const DEFAULT_OG = "/images/brand/og-default.jpg";
const CARD = { width: 1200, height: 630 };

export function pageMeta(input: {
  title: string;
  description: string;
  path: string;
  image?: string;
  noIndex?: boolean;
  type?: "website" | "article";
  /** Skip the "| CAPRA" template when the title already carries the brand. */
  absoluteTitle?: boolean;
  publishedTime?: string;
  modifiedTime?: string;
  keywords?: string[];
}): Metadata {
  const url = `${BRAND.domain}${input.path}`;
  const own = input.image && /\.(jpe?g|png)$/.test(input.image) ? input.image : null;
  const shareable = own ?? (input.noIndex ? DEFAULT_OG : `/og?path=${encodeURIComponent(input.path)}`);
  const image = `${BRAND.domain}${shareable}`;
  const { title, description } = input;
  return {
    title: input.absoluteTitle ? { absolute: title } : title,
    description,
    ...(input.keywords?.length ? { keywords: input.keywords } : {}),
    // A noindex page (404, basket, admin) must not claim a canonical URL of its own.
    alternates: input.noIndex ? undefined : { canonical: url, types: { "text/markdown": `${BRAND.domain}${input.path === "/" ? "/index" : input.path}.md` } },
    robots: input.noIndex
      ? { index: false, follow: false, googleBot: { index: false, follow: false } }
      : { index: true, follow: true, googleBot: { index: true, follow: true, "max-image-preview": "large", "max-snippet": -1, "max-video-preview": -1 } },
    openGraph: {
      title, description, url, siteName: BRAND.name, locale: "en_PK", type: input.type ?? "website",
      ...(input.publishedTime ? { publishedTime: input.publishedTime } : {}),
      ...(input.modifiedTime ? { modifiedTime: input.modifiedTime } : {}),
      images: [{ url: image, ...CARD, alt: title }],
    },
    twitter: { card: "summary_large_image", title, description, images: [image] },
  };
}

/* ─── JSON-LD builders ───────────────────────────────────────────────────── */

export const ORG_ID = `${BRAND.domain}/#organization`;
export const SITE_ID = `${BRAND.domain}/#website`;

const areaServed = [...SERVICE_AREAS.map((name) => ({ "@type": "City" as const, name })), { "@type": "Country" as const, name: "Pakistan" }];

/** The manufacturer and online store, as one entity every other node points at. */
export const organizationLd = () => ({
  "@context": "https://schema.org",
  "@type": ["Organization", "OnlineStore", "LocalBusiness"],
  "@id": ORG_ID,
  name: BRAND.name,
  alternateName: "CAPRA Pakistan",
  legalName: BRAND.legalName,
  description: `${BRAND.name} is a vacuum flask brand made by ${BRAND.legalName} in ${BRAND.address.city}, Pakistan, since ${BRAND.founded}. It makes stainless steel vacuum jugs from 1 to 3 litres, insulated sports bottles and bullet flasks, and sells them online across Pakistan with cash on delivery.`,
  slogan: BRAND.tagline,
  url: BRAND.domain,
  logo: { "@type": "ImageObject", "@id": `${BRAND.domain}/#logo`, url: `${BRAND.domain}${BRAND.logoSquare}`, width: 512, height: 512, caption: BRAND.name },
  image: `${BRAND.domain}${BRAND.logoSquare}`,
  email: CONTACT.email,
  telephone: CONTACT.phoneTel.replace("tel:", ""),
  foundingDate: BRAND.founded,
  priceRange: `Rs ${listPriceBounds().min.toLocaleString("en-PK")} – Rs ${listPriceBounds().max.toLocaleString("en-PK")}`,
  currenciesAccepted: COMMERCIAL.currency,
  paymentAccepted: "Cash on delivery, Bank transfer, JazzCash, Easypaisa",
  address: { "@type": "PostalAddress", streetAddress: BRAND.address.street, addressLocality: BRAND.address.city, addressRegion: BRAND.address.region, addressCountry: "PK" },
  geo: { "@type": "GeoCoordinates", latitude: BRAND.geo.latitude, longitude: BRAND.geo.longitude },
  areaServed,
  knowsLanguage: ["en-PK", "ur-PK"],
  contactPoint: [
    { "@type": "ContactPoint", contactType: "customer service", telephone: CONTACT.phoneTel.replace("tel:", ""), email: CONTACT.email, areaServed: "PK", availableLanguage: ["English", "Urdu"] },
    { "@type": "ContactPoint", contactType: "sales", telephone: CONTACT.whatsappIntl, areaServed: "PK", availableLanguage: ["English", "Urdu"] },
  ],
  openingHoursSpecification: [{ "@type": "OpeningHoursSpecification", dayOfWeek: BRAND.hours.days, opens: BRAND.hours.opens, closes: BRAND.hours.closes }],
  hasMerchantReturnPolicy: returnPolicyLd(),
  sameAs: Object.values(SOCIAL),
});

export const websiteLd = () => ({
  "@context": "https://schema.org",
  "@type": "WebSite",
  "@id": SITE_ID,
  url: BRAND.domain,
  name: BRAND.name,
  description: BRAND.description,
  inLanguage: "en-PK",
  publisher: { "@id": ORG_ID },
});

export const breadcrumbLd = (items: { name: string; path: string }[]) => ({
  "@context": "https://schema.org",
  "@type": "BreadcrumbList",
  itemListElement: [{ name: "Home", path: "/" }, ...items].map((it, i) => ({ "@type": "ListItem", position: i + 1, name: it.name, item: `${BRAND.domain}${it.path}` })),
});

export const faqLd = (faq: { q: string; a: string }[]) => ({
  "@context": "https://schema.org",
  "@type": "FAQPage",
  mainEntity: faq.map((f) => ({ "@type": "Question", name: f.q, acceptedAnswer: { "@type": "Answer", text: f.a } })),
});

function returnPolicyLd() {
  return {
    "@type": "MerchantReturnPolicy",
    applicableCountry: "PK",
    returnPolicyCategory: "https://schema.org/MerchantReturnFiniteReturnWindow",
    merchantReturnDays: COMMERCIAL.returnDays,
    returnMethod: "https://schema.org/ReturnByMail",
    returnFees: "https://schema.org/FreeReturn",
  };
}

const shippingLd = (price: number) => ({
  "@type": "OfferShippingDetails",
  shippingRate: { "@type": "MonetaryAmount", value: price >= COMMERCIAL.freeDeliveryFrom ? 0 : COMMERCIAL.deliveryFee, currency: COMMERCIAL.currency },
  shippingDestination: { "@type": "DefinedRegion", addressCountry: "PK" },
  deliveryTime: {
    "@type": "ShippingDeliveryTime",
    handlingTime: { "@type": "QuantitativeValue", minValue: 1, maxValue: 2, unitCode: "DAY" },
    transitTime: { "@type": "QuantitativeValue", minValue: 2, maxValue: 5, unitCode: "DAY" },
  },
});

/**
 * A series with sizes and colours as a ProductGroup of real variants, each with its own SKU and price, so
 * Google can show "Rs 1,480 – Rs 2,000" and the exact model. Ratings and reviews are never invented.
 */
export const productGroupLd = (p: {
  name: string; description: string; path: string; images: string[]; groupId: string; availability: "InStock" | "OutOfStock";
  variants: { sku: string; name: string; size: string; colour: string; price: number; image: string; litres: number }[];
}) => ({
  "@context": "https://schema.org",
  "@type": "ProductGroup",
  name: p.name,
  description: p.description,
  url: `${BRAND.domain}${p.path}`,
  image: p.images.map((i) => `${BRAND.domain}${i}`),
  brand: { "@type": "Brand", name: BRAND.name },
  manufacturer: { "@id": ORG_ID },
  productGroupID: p.groupId,
  variesBy: ["https://schema.org/size", "https://schema.org/color"],
  material: "Stainless steel",
  countryOfOrigin: "PK",
  hasVariant: p.variants.map((v) => ({
    "@type": "Product",
    sku: v.sku,
    mpn: v.sku,
    name: v.name,
    size: v.size,
    color: v.colour,
    image: `${BRAND.domain}${v.image}`,
    additionalProperty: [{ "@type": "PropertyValue", name: "Capacity", value: v.litres, unitCode: "LTR" }],
    offers: {
      "@type": "Offer",
      price: v.price,
      priceCurrency: COMMERCIAL.currency,
      availability: `https://schema.org/${p.availability}`,
      itemCondition: "https://schema.org/NewCondition",
      url: `${BRAND.domain}${p.path}`,
      seller: { "@id": ORG_ID },
      shippingDetails: shippingLd(v.price),
      hasMerchantReturnPolicy: returnPolicyLd(),
    },
  })),
});

/** A listing page: the products on it, in order, for carousels and answer engines. */
export const itemListLd = (name: string, items: { name: string; path: string }[]) => ({
  "@context": "https://schema.org",
  "@type": "ItemList",
  name,
  itemListElement: items.map((it, i) => ({ "@type": "ListItem", position: i + 1, name: it.name, url: `${BRAND.domain}${it.path}` })),
});

export const articleLd = (a: { title: string; description: string; path: string; date: string; modified?: string; image?: string; keywords?: string[]; author?: string | null }) => ({
  "@context": "https://schema.org",
  "@type": "BlogPosting",
  headline: a.title,
  description: a.description,
  url: `${BRAND.domain}${a.path}`,
  mainEntityOfPage: `${BRAND.domain}${a.path}`,
  image: a.image ? `${BRAND.domain}${a.image}` : undefined,
  datePublished: a.date,
  dateModified: a.modified ?? a.date,
  inLanguage: "en-PK",
  keywords: a.keywords?.length ? a.keywords.join(", ") : undefined,
  author: a.author ? { "@type": "Person", name: a.author } : { "@id": ORG_ID },
  publisher: { "@id": ORG_ID },
});

export function JsonLd({ data }: { data: object | undefined | (object | undefined)[] }) {
  const nodes = (Array.isArray(data) ? data : [data]).filter(Boolean);
  if (!nodes.length) return null;
  return <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(nodes).replace(/</g, "\\u003c") }} />;
}
